+function request(port, servername, expectedCertificate) {
+  return new Promise((resolve, reject) => {
+    const req = https.get({
+      host: '127.0.0.1',
+      port,
+      servername,
+      rejectUnauthorized: false,
+      agent: false,
+    }, common.mustCall((response) => {
