+
+typedef float f3 __attribute__((ext_vector_type (3)));
+
+static f3
+scale3 (f3 v)
+{
+  f3 r;
+  r[0] = v[0] + 1;
+  r[1] = v[1] + 2;
+  r[2] = v[2] + 3;
+  return r;
+}
